{
  "providers": [
    {
      "platform": "host",
      "id": "Service",
      "description": "Progressive Host Service discovery: compact capability/signature directory, then one exact coding contract.",
      "methods": [
        {
          "name": "listService",
          "description": "Progressive Host Service discovery: compact capability/signature directory, then one exact coding contract.",
          "inputSchema": {
            "type": "object",
            "properties": {
              "service": {
                "type": "string",
                "description": "Exact Service key. Omit it for the compact Service and method-signature directory."
              }
            },
            "additionalProperties": false
          },
          "outputSchema": {
            "description": "Compact Service directory, or one exact Service contract with only its referenced type declarations."
          }
        }
      ]
    },
    {
      "platform": "host",
      "id": "Event",
      "description": "Progressive Host Event discovery: compact listener directory, then one exact event contract.",
      "methods": [
        {
          "name": "listEvents",
          "description": "Progressive Host Event discovery: compact listener directory, then one exact event contract.",
          "inputSchema": {
            "type": "object",
            "properties": {
              "event": {
                "type": "string",
                "description": "Exact Event name. Omit it for the compact Event and listener-signature directory."
              }
            },
            "additionalProperties": false
          },
          "outputSchema": {
            "description": "Compact Event directory, or one exact Event contract with only its referenced type declarations."
          }
        }
      ]
    },
    {
      "platform": "host",
      "id": "Builtin",
      "description": "Plain-JavaScript symbols available to a dynamic Host half.",
      "methods": [
        {
          "name": "listBuiltins",
          "description": "Plain-JavaScript symbols available to a dynamic Host half.",
          "inputSchema": {
            "type": "object",
            "properties": {},
            "additionalProperties": false
          },
          "outputSchema": {
            "description": "JSON data owned by this inspect provider."
          }
        }
      ]
    },
    {
      "platform": "host",
      "id": "Tool",
      "description": "Tools visible to the requesting Agent, including scoped and dynamic registrations.",
      "methods": [
        {
          "name": "listTools",
          "description": "Return every Tool schema currently callable by this Agent.",
          "inputSchema": {
            "type": "object",
            "properties": {},
            "additionalProperties": false
          },
          "outputSchema": {
            "description": "JSON data owned by this inspect provider."
          }
        }
      ]
    },
    {
      "platform": "client",
      "id": "Service",
      "description": "Progressive Client Service discovery: compact capability/signature directory, then one exact coding contract.",
      "methods": [
        {
          "name": "listService",
          "description": "Progressive Client Service discovery: compact capability/signature directory, then one exact coding contract.",
          "inputSchema": {
            "type": "object",
            "properties": {
              "service": {
                "type": "string",
                "description": "Exact Service key. Omit it for the compact Service and method-signature directory."
              }
            },
            "additionalProperties": false
          },
          "outputSchema": {
            "description": "Compact Service directory, or one exact Service contract with only its referenced type declarations."
          }
        }
      ]
    },
    {
      "platform": "client",
      "id": "Event",
      "description": "Progressive Client Event discovery: compact listener directory, then one exact event contract.",
      "methods": [
        {
          "name": "listEvents",
          "description": "Progressive Client Event discovery: compact listener directory, then one exact event contract.",
          "inputSchema": {
            "type": "object",
            "properties": {
              "event": {
                "type": "string",
                "description": "Exact Event name. Omit it for the compact Event and listener-signature directory."
              }
            },
            "additionalProperties": false
          },
          "outputSchema": {
            "description": "Compact Event directory, or one exact Event contract with only its referenced type declarations."
          }
        }
      ]
    },
    {
      "platform": "client",
      "id": "Builtin",
      "description": "Plain-JavaScript symbols available to a dynamic Client half.",
      "methods": [
        {
          "name": "listBuiltins",
          "description": "Plain-JavaScript symbols available to a dynamic Client half.",
          "inputSchema": {
            "type": "object",
            "properties": {},
            "additionalProperties": false
          },
          "outputSchema": {
            "description": "JSON data owned by this inspect provider."
          }
        }
      ]
    },
    {
      "platform": "client",
      "id": "Slots",
      "description": "Progressive live Slot inspection: compact purpose/topology trees plus one exact Slot contract.",
      "methods": [
        {
          "name": "listSubTree",
          "description": "Return compact live Slot trees for navigation. With root, also return the selected Slot's full contract and occupants.",
          "inputSchema": {
            "type": "object",
            "properties": {
              "root": {
                "type": "string",
                "description": "Exact live Slot key. When supplied, selected contains the full contract for this Slot."
              }
            },
            "additionalProperties": false
          },
          "outputSchema": {
            "description": "Compact purpose/topology trees. With root, selected also contains that Slot's full contract and live occupants."
          }
        }
      ]
    },
    {
      "platform": "client",
      "id": "Theme",
      "description": "Current theme token names and light/dark override requirements.",
      "methods": [
        {
          "name": "listTokens",
          "description": "Current theme token names and light/dark override requirements.",
          "inputSchema": {
            "type": "object",
            "properties": {},
            "additionalProperties": false
          },
          "outputSchema": {
            "description": "JSON data owned by this inspect provider."
          }
        }
      ]
    }
  ]
}

{
  "platform": "host",
  "provider": "Tool",
  "method": "listTools",
  "data": {
    "tools": [
      {
        "name": "cordis_inspect_list",
        "description": "List every Cordis Inspect Provider currently known to the Host, including local Host Providers and the latest manifests synchronized from the Client. Each entry includes its platform, purpose, read-only methods, and input/output schemas. Call this Tool before creating or modifying a Package, then select the provider and method for cordis_inspect_query from its result. Do not guess names or treat an Inspect method as a business Service that Plugin code can call.",
        "parameters": {
          "type": "object",
          "properties": {}
        }
      },
      {
        "name": "cordis_inspect_query",
        "description": "Run a read-only query explicitly declared by an Inspect Provider. platform, provider, and method must come from cordis_inspect_list, and input must satisfy that method's schema. Use this Tool before cordis_define to read exact Service methods, Event modes, Builtin signatures, Tool schemas, theme tokens, or live Slot trees and props. Host queries run locally. A Client query waits for the first valid page response and remains pending until a page answers or the Tool is cancelled. This Tool cannot invoke business Service methods or modify the runtime. For Service.listService and Event.listEvents, query without input to navigate the compact signature directory, then query the exact service or event for its structured contract and referenced types. For Slots.listSubTree, query without root to navigate the compact tree, then query the exact root for its complete registration contract and props.",
        "parameters": {
          "type": "object",
          "properties": {
            "platform": {
              "type": "string",
              "description": "Runtime platform that owns the Provider.",
              "enum": [
                "host",
                "client"
              ]
            },
            "provider": {
              "type": "string",
              "description": "Exact Provider ID returned by cordis_inspect_list."
            },
            "method": {
              "type": "string",
              "description": "Exact method name declared by the Provider manifest."
            },
            "input": {
              "description": "Optional query input; it must satisfy the method input schema."
            }
          },
          "required": [
            "platform",
            "provider",
            "method"
          ]
        }
      },
      {
        "name": "cordis_inspect_self",
        "description": "Inspect dynamic Cordis objects owned by the current Session at increasing levels of detail. With no IDs, list only Plugin summaries. With pluginId alone, return version pointers, the latest Run, and every Package summary. Only pluginId plus packageId returns that immutable Package's Host/Client source and runtime diagnostics. packageId cannot be supplied alone. Query an exact Package before handling @pluginId, repairing an asynchronous failure, or defining an updated version. This Tool is read-only: it neither executes code nor changes version pointers.",
        "parameters": {
          "type": "object",
          "properties": {
            "pluginId": {
              "type": "string",
              "description": "Stable Plugin ID returned by cordis_define or injected by @pluginId; omit it to list every current Plugin."
            },
            "packageId": {
              "type": "string",
              "description": "Exact immutable Package ID owned by pluginId; when specified, source and diagnostics are returned."
            }
          }
        }
      },
      {
        "name": "cordis_define",
        "description": "Define an immutable Cordis Package. For a new Plugin, use kind:\"new\" and provide only a semantic prefix of 3–6 lowercase English letters; the Host returns the final pluginId and packageId. To modify an existing Plugin, use kind:\"existing\" with its exact pluginId to append a Package without overwriting older versions. Provide at least one of code.host and code.client. Each value is a plain JavaScript function body that returns a Cordis Plugin; no TypeScript, JSX, or import transformation occurs. Query Inspect before depending on a Service, Event, Builtin, Slot, or token. Define only validates parameters and syntax and records source: it does not request approval, execute apply, or change currentPackageId. On success, call cordis_run with the returned IDs.",
        "parameters": {
          "type": "object",
          "properties": {
            "plugin": {
              "oneOf": [
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "kind": {
                      "type": "string",
                      "const": "new"
                    },
                    "idPrefix": {
                      "type": "string",
                      "description": "Suggested semantic prefix of 3–6 lowercase English letters; the Host adds a unique numeric suffix."
                    }
                  },
                  "required": [
                    "kind",
                    "idPrefix"
                  ]
                },
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "kind": {
                      "type": "string",
                      "const": "existing"
                    },
                    "pluginId": {
                      "type": "string",
                      "description": "Exact ID of an existing Plugin; the new Package is appended to that instance."
                    }
                  },
                  "required": [
                    "kind",
                    "pluginId"
                  ]
                }
              ]
            },
            "name": {
              "type": "string",
              "description": "Short, readable Package name."
            },
            "purpose": {
              "type": "string",
              "description": "One-sentence, user-facing description of the Package purpose."
            },
            "code": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "host": {
                  "type": "string",
                  "description": "Plain JavaScript function body that returns the Host-half Cordis Plugin."
                },
                "client": {
                  "type": "string",
                  "description": "Plain JavaScript function body that returns the browser Client-half Cordis Plugin."
                }
              }
            }
          },
          "required": [
            "plugin",
            "name",
            "purpose",
            "code"
          ]
        }
      },
      {
        "name": "cordis_run",
        "description": "Activate one exact Package of a dynamic Plugin. Use mode:\"run\" for the first activation, restarting currentPackageId, or rollback. When current exists, use mode:\"update\" to switch to a different Package, even if the Plugin is currently stopped. An unauthorized Client Package creates an approval request and returns awaiting-approval; an authorized Package returns starting and continues asynchronously in the browser. Neither result waits for the final outcome inside the Tool. currentPackageId changes only after complete success; on failure, the old current and target next remain. Asynchronous success, rejection, or technical failure is reported through state and steering. After a technical failure, read diagnostics with cordis_inspect_self, correct the same Plugin, and retry autonomously. Do not request approval again after the user rejects it.",
        "parameters": {
          "type": "object",
          "properties": {
            "pluginId": {
              "type": "string",
              "description": "Stable Plugin ID returned by cordis_define."
            },
            "packageId": {
              "type": "string",
              "description": "Exact immutable Package ID to activate under that Plugin."
            },
            "mode": {
              "type": "string",
              "description": "Use run for the first activation, restarting current, or rollback; use update to switch from current to a different Package.",
              "enum": [
                "run",
                "update"
              ]
            }
          },
          "required": [
            "pluginId",
            "packageId",
            "mode"
          ]
        }
      },
      {
        "name": "cordis_stop",
        "description": "Stop the current Run of a dynamic Plugin and cancel unfinished approval or activation requests. Retain the Plugin, every immutable Package, grants, currentPackageId, and nextPackageId so it can later run or update directly. Stopping an already stopped Plugin succeeds idempotently. Use this Tool to disable effects temporarily; use cordis_undefine for permanent removal.",
        "parameters": {
          "type": "object",
          "properties": {
            "pluginId": {
              "type": "string",
              "description": "Stable dynamic Plugin ID to stop."
            }
          },
          "required": [
            "pluginId"
          ]
        }
      },
      {
        "name": "cordis_undefine",
        "description": "Permanently remove a dynamic Plugin owned by the current Session. If it is running or awaiting approval, first stop it and cancel the request, then delete every Package, grant, and version pointer. After this returns, its pluginId, packageIds, @ reference, and Package business views are invalid; historical cards retain only a \"Plugin removed\" record. Do not call this Tool when versions must remain available for restart or rollback; use cordis_stop instead.",
        "parameters": {
          "type": "object",
          "properties": {
            "pluginId": {
              "type": "string",
              "description": "Stable dynamic Plugin ID to remove permanently."
            }
          },
          "required": [
            "pluginId"
          ]
        }
      },
      {
        "name": "job_output",
        "description": "Read a background job. Stream jobs return only output since the previous read; final-output jobs return their result after settlement. Every response ends with `[status: ...]`. Reads are non-blocking unless `wait: true`, which waits up to the configured cap.",
        "parameters": {
          "type": "object",
          "properties": {
            "job_id": {
              "type": "string",
              "description": "Job id returned by the tool that started the background work."
            },
            "wait": {
              "type": "boolean",
              "description": "Block until the job reaches a terminal status or the timeout expires. A timed-out wait returns [status: running] and leaves the job alive."
            },
            "timeout_ms": {
              "type": "number",
              "description": "Max wait in milliseconds (only meaningful with wait: true). Defaults to the configured wait timeout; capped by the configured maximum."
            }
          },
          "required": [
            "job_id"
          ]
        }
      },
      {
        "name": "job_list",
        "description": "List your background jobs (running and finished) with their ids, kinds, and statuses.",
        "parameters": {
          "type": "object",
          "properties": {}
        }
      },
      {
        "name": "job_kill",
        "description": "Request cancellation of a running background job by job id. Returns immediately; the job settles as killed once its work actually stops.",
        "parameters": {
          "type": "object",
          "properties": {
            "job_id": {
              "type": "string",
              "description": "Job id returned by the tool that started the background work."
            },
            "reason": {
              "type": "string",
              "description": "Optional short reason, recorded in the log and forwarded to the job."
            }
          },
          "required": [
            "job_id"
          ]
        }
      },
      {
        "name": "skill",
        "description": "Load the full instructions for an available skill. Call this with the exact skill name from the session skill catalog before acting on a task that names or clearly matches that skill.",
        "parameters": {
          "type": "object",
          "properties": {
            "name": {
              "type": "string",
              "description": "The exact skill name from the available skills list."
            }
          },
          "required": [
            "name"
          ]
        }
      },
      {
        "name": "ask_user_question",
        "description": "Ask the user a concise question when you need confirmation, a choice, or missing information before proceeding. Send one or more questions, each with a stable id that will be echoed in the answer.",
        "parameters": {
          "type": "object",
          "properties": {
            "questions": {
              "type": "array",
              "description": "Questions to ask the user before continuing.",
              "items": {
                "type": "object",
                "additionalProperties": true,
                "properties": {
                  "id": {
                    "type": "string",
                    "description": "Stable id for this question; echoed in the answer."
                  },
                  "question": {
                    "type": "string",
                    "description": "The specific question to ask the user."
                  },
                  "header": {
                    "type": "string",
                    "description": "Optional short heading for the question, such as \"Confirm\" or \"Choose Mode\"."
                  },
                  "options": {
                    "type": "array",
                    "description": "Optional choices to show the user. If you recommend one, put it first and append \"(Recommended)\" to that label.",
                    "items": {
                      "type": "object",
                      "additionalProperties": true,
                      "properties": {
                        "label": {
                          "type": "string",
                          "description": "Short user-facing option label."
                        },
                        "description": {
                          "type": "string",
                          "description": "One sentence explaining the tradeoff or impact."
                        }
                      },
                      "required": [
                        "label"
                      ]
                    }
                  },
                  "multi_select": {
                    "type": "boolean",
                    "description": "Whether the user may select more than one option. Defaults to false."
                  }
                },
                "required": [
                  "id",
                  "question"
                ]
              }
            }
          },
          "required": [
            "questions"
          ]
        }
      },
      {
        "name": "todo_write",
        "description": "Record and update a structured task list for the current work. Send the ENTIRE list every call — it REPLACES the previous list (there are no partial updates, no per-item edits). Use it to plan multi-step work and show progress: add one todo per concrete step before you start. Mark every todo being actively worked on `in_progress` — several at once when work genuinely runs in parallel (e.g. concurrent subagents or background commands), one for sequential work; while work remains, at least one task should be `in_progress`. Mark a todo `completed` the moment it is done (do not batch completions), and allow no `in_progress` item only once all work is complete. Skip the list for trivial single-step tasks. Statuses: `pending` (not started), `in_progress` (being worked on now), `completed` (finished).",
        "parameters": {
          "type": "object",
          "properties": {
            "todos": {
              "type": "array",
              "description": "The COMPLETE task list, replacing any previous list.",
              "items": {
                "type": "object",
                "additionalProperties": false,
                "properties": {
                  "content": {
                    "type": "string",
                    "description": "What the task is — a short imperative line."
                  },
                  "status": {
                    "type": "string",
                    "description": "pending (not started) | in_progress (now) | completed (done).",
                    "enum": [
                      "pending",
                      "in_progress",
                      "completed"
                    ]
                  }
                },
                "required": [
                  "content",
                  "status"
                ]
              }
            }
          },
          "required": [
            "todos"
          ]
        }
      },
      {
        "name": "exit_plan_mode",
        "description": "Use only in plan mode. Present your plan for the user's review and, on approval, leave plan mode. Send the COMPLETE plan as markdown, starting with a # heading that names it. The user may approve (carry out the plan from your next step) or keep planning — their feedback comes back in the tool result; revise and present again.",
        "parameters": {
          "type": "object",
          "properties": {
            "plan": {
              "type": "string",
              "description": "The complete plan, as markdown, starting with a # heading that names it."
            }
          },
          "required": [
            "plan"
          ]
        }
      },
      {
        "name": "send_message",
        "description": "Send a message to a background subagent by its subagent id, continuing the same conversation. It becomes the subagent's next turn: if it is still working, the message waits until its current turn finishes, so it cannot redirect work already underway. This call returns no answer from the subagent — only confirmation that the message was delivered — so use it to give it more work. A failure means the message was NOT delivered.",
        "parameters": {
          "type": "object",
          "properties": {
            "subagent_id": {
              "type": "string",
              "description": "The subagent id returned when the background subagent was started."
            },
            "message": {
              "type": "string",
              "description": "The message to deliver to the subagent."
            }
          },
          "required": [
            "subagent_id",
            "message"
          ]
        }
      },
      {
        "name": "interrupt_agent",
        "description": "Request cancellation of a background agent's current turn by its agent id. The target may be your direct child or a deeper agent created under you. Only the current turn stops: messages already queued for the agent stay parked until a later send_message, agents it started keep running, and the agent itself stays available for follow-ups. This call returns as soon as the stop request is accepted, so the target may keep running briefly; interrupting an agent that already finished is an accepted no-op.",
        "parameters": {
          "type": "object",
          "properties": {
            "agent_id": {
              "type": "string",
              "description": "The agent id of the running agent to interrupt."
            }
          },
          "required": [
            "agent_id"
          ]
        }
      },
      {
        "name": "list_agents",
        "description": "List your continuable background subagents by durable id and label. Use it to recall which ones you started, not to poll for completion — you are told when one finishes. Status comes from the live registry: running means the agent is working right now, idle means it is loaded but between turns (it may be waiting on agents it started), and ready means it exists only in storage — resumable, not terminal, and not a result waiting to be collected; a `send_message` starts a new turn on the same conversation, and a direct child remains a `send_message` candidate in every status. The snapshot is not a delivery promise — `send_message` performs the authoritative check and may still fail. Children that could not be read are reported as diagnostics instead of being silently dropped. Scope `descendants` walks the whole tree below you in stable pre-order, annotating each entry with its durable direct-parent session id and depth. You may use `send_message` only for depth-1 entries; deeper entries are candidates for `interrupt_agent` only.",
        "parameters": {
          "type": "object",
          "properties": {
            "scope": {
              "type": "string",
              "description": "children (default) lists direct children only; descendants walks the complete tree below you.",
              "enum": [
                "children",
                "descendants"
              ]
            }
          }
        }
      },
      {
        "name": "subagent",
        "description": "Delegate a self-contained task to a subagent (a separate agent that works in its own context) to offload focused, independent work — research, a scoped implementation, an analysis — so it does not consume this conversation's context. The subagent returns its result, not its intermediate steps. Give it a complete, standalone prompt: it does not see this conversation. This tool runs in the background by default, immediately returns a durable subagent id, and keeps the child conversation available for later turns. When that run settles, the runtime sends the parent a notice containing its outcome and any final assistant message; `send_message` starts a later turn in the same child conversation. Set `run_in_background: false` only when your next action depends on receiving the result.",
        "parameters": {
          "type": "object",
          "properties": {
            "description": {
              "type": "string",
              "description": "A short (3-5 word) description of the delegated task, for display."
            },
            "prompt": {
              "type": "string",
              "description": "The complete, self-contained task for the subagent. It does not share this conversation's context, so include everything it needs."
            },
            "run_in_background": {
              "type": "boolean",
              "description": "Whether to run in the background and return a durable subagent id immediately. Defaults to true. Set false to wait for the result when your next action depends on it."
            }
          },
          "required": [
            "description",
            "prompt"
          ]
        }
      },
      {
        "name": "subagent_fork",
        "description": "Delegate a task to a subagent that inherits this conversation: a child agent seeded with all completed turns so far (it does not see the current in-flight turn). Use this when the subtask builds on this conversation's context — a follow-up analysis, a review, a continuation — without consuming this conversation's context for the work itself. You receive its result, not its intermediate steps. This tool runs in the background by default, immediately returns a durable subagent id, and keeps the child conversation available for later turns. When that run settles, the runtime sends the parent a notice containing its outcome and any final assistant message; `send_message` starts a later turn in the same child conversation. Set `run_in_background: false` only when your next action depends on receiving the result.",
        "parameters": {
          "type": "object",
          "properties": {
            "description": {
              "type": "string",
              "description": "A short (3-5 word) description of the delegated task, for display."
            },
            "prompt": {
              "type": "string",
              "description": "The task for the subagent. It already sees this conversation's completed turns, so build on them freely and state only what is new."
            },
            "run_in_background": {
              "type": "boolean",
              "description": "Whether to run in the background and return a durable subagent id immediately. Defaults to true. Set false to wait for the result when your next action depends on it."
            }
          },
          "required": [
            "description",
            "prompt"
          ]
        }
      },
      {
        "name": "pwsh",
        "description": "Execute a PowerShell command (`pwsh -Command`) and return its stdout/stderr. Each call runs in a fresh pwsh process: no state (cwd, variables, functions) persists between calls — pass `workdir` instead of using `cd`. Paths use native Windows form (`C:\\...`); read environment variables with `$env:NAME`. Non-zero exits are reported as `[exit code: N]`. Current harness environment facts are exposed through managed `$env:DSH_*` variables; inspect them when needed. Commands may run under a file sandbox; a blocked file operation is reported as `[sandbox: file access denied under <mode> mode]` — a policy denial, not a bug in the command; do not retry another way. Long output is truncated to its tail; the full output is saved to a file whose path is reported when available. On Windows a force-killed command settles as `[exit code: 1]` without a signal marker — treat it as an interruption, not a command failure. Set `run_in_background: true` for long-running commands: the call returns a job id immediately; read its output with `job_output` and stop it with `job_kill`. Under the Windows sandbox, read-only pwsh runs in PowerShell ConstrainedLanguage mode, while workspace-write stays in FullLanguage unless host policy says otherwise. In read-only, prefer cmdlets and core types (`[string]`, `[datetime]`, `[regex]`, `[guid]`); .NET static calls (`[System.IO.*]::`, `[math]::`), `Add-Type`, COM objects, and reflection fail with \"only core types\" errors. `-f` formatting, property access, and core cmdlets work. In both confined modes, programs cannot open named pipes, so a command that captures another program's output through piped stdio (Node.js `child_process.spawn`/`exec` with the default `stdio: 'pipe'`) fails with EPERM, while `stdio: 'inherit'` and `stdio: 'ignore'` spawns work and PowerShell's own pipelines are unaffected. That EPERM is the documented boundary: do not retry the command another way — escalate the exact command once or restructure it to avoid capturing output. Attempting a command the sandbox may deny is safe and expected: run it and read the marker rather than assuming the denial. When a command is denied and a wider mode would let it succeed, escalate immediately in the same turn — the one sanctioned exception to a denial: retry the exact same command once with `sandbox_permissions` (the narrowest wider mode that suffices) plus a one-sentence `justification`. Do not detour through chat to ask permission first — the approval prompt raised by that retry is how the user consents. If the session states approval prompts are disabled, there is no exception: a denial is final — do not set `sandbox_permissions`. Never escalate speculatively: ground the request in a real denial — normally the one this command just hit; escalating up front is fine only when this session already denied the same access. A rejected escalation is final for that command — stop and explain, never work around it — but it does not forbid attempting or escalating other commands later.",
        "parameters": {
          "type": "object",
          "properties": {
            "command": {
              "type": "string",
              "description": "The PowerShell command to execute."
            },
            "description": {
              "type": "string",
              "description": "Clear, concise description of what this command does in active voice, 5-10 words (shown in the UI). Examples: \"ls\" → \"List files in current directory\"; \"git status\" → \"Show working tree status\"; \"Get-Process\" → \"List running processes\"."
            },
            "timeoutMs": {
              "type": "number",
              "description": "Timeout in milliseconds. The executor applies its configured default and cap, and kills the command on expiry."
            },
            "workdir": {
              "type": "string",
              "description": "Working directory for this command. Defaults to the session workspace; a relative path is resolved against it."
            },
            "run_in_background": {
              "type": "boolean",
              "description": "Run in the background and return a job id immediately (collect with job_output, stop with job_kill). No timeout applies."
            },
            "sandbox_permissions": {
              "type": "string",
              "description": "The wider sandbox mode this command needs. Only valid as a one-shot retry of a command the sandbox just denied; requires justification and user approval.",
              "enum": [
                "workspace-write",
                "danger-full-access"
              ]
            },
            "justification": {
              "type": "string",
              "description": "Required with sandbox_permissions: one sentence for the user explaining why this exact command needs the wider access."
            }
          },
          "required": [
            "command",
            "description"
          ]
        }
      },
      {
        "name": "get_goal",
        "description": "Read the current same-session goal, including its exact id/revision, objective, phase, completed continuation rounds, round limit, blocker reason when present, and whether another continuation is armed. Call this before updating a goal.",
        "parameters": {
          "type": "object",
          "properties": {}
        }
      },
      {
        "name": "create_goal",
        "description": "Create one persisted same-session completion goal when the current direct human request is a long-running objective that should continue across autonomous goal rounds. You may infer that intent without requiring the user to say \"create a goal\". Do not use this for trivial single-turn work. Execution rejects non-human and subagent authority.",
        "parameters": {
          "type": "object",
          "properties": {
            "objective": {
              "type": "string",
              "description": "The concrete completion objective inferred from the direct human request."
            },
            "max_goal_rounds": {
              "type": "number",
              "description": "Optional positive safe-integer limit on automatic continuation rounds."
            }
          },
          "required": [
            "objective"
          ]
        }
      },
      {
        "name": "update_goal",
        "description": "Update the exact current goal revision. edit, pause, and resume require a direct top-level human request. During an automatic continuation of the current goal, complete and blocked are also allowed. blocked is rejected before the configured minimum round count; the model remains responsible for judging that the same condition persisted across those rounds and must explain it in blocked_reason.",
        "parameters": {
          "type": "object",
          "properties": {
            "goal_id": {
              "type": "string",
              "description": "Exact id returned by get_goal."
            },
            "revision": {
              "type": "number",
              "description": "Exact positive revision returned by get_goal."
            },
            "action": {
              "type": "string",
              "description": "edit | pause | resume | complete | blocked",
              "enum": [
                "edit",
                "pause",
                "resume",
                "complete",
                "blocked"
              ]
            },
            "objective": {
              "type": "string",
              "description": "Replacement objective; valid only with action edit."
            },
            "max_goal_rounds": {
              "type": "number",
              "description": "Replacement cap; valid only with action edit."
            },
            "blocked_reason": {
              "type": "string",
              "description": "Concrete blocking condition; required only with action blocked."
            }
          },
          "required": [
            "goal_id",
            "revision",
            "action"
          ]
        }
      },
      {
        "name": "glob",
        "description": "Find files whose paths match a glob pattern. Returns matching file paths — never directories — including hidden and ignored files (VCS metadata directories are excluded). Up to 100 paths come back in modification-time order; a larger result returns the first 100 paths in modification-time order, says so, and reports where the complete sorted list was saved. This tool does not enumerate directory entries.",
        "parameters": {
          "type": "object",
          "properties": {
            "pattern": {
              "type": "string",
              "description": "Glob pattern to match file paths against (e.g. \"**/*.ts\", \"src/**/*.test.js\"). A pattern with no \"/\" matches the basename at any depth, so \"*\" and \"*.ts\" both search the whole tree; include a separator to anchor the depth."
            },
            "path": {
              "type": "string",
              "description": "Directory to search in. Defaults to the session workspace; a relative path resolves against it."
            }
          },
          "required": [
            "pattern"
          ]
        }
      },
      {
        "name": "grep",
        "description": "Search file contents with a ripgrep regular expression. Returns matching lines with line numbers, grouped by file. Returns the first 250 matches inline; a capped result reports where the complete match list was saved. Use read on a matched file for surrounding context.",
        "parameters": {
          "type": "object",
          "properties": {
            "pattern": {
              "type": "string",
              "description": "Regular expression to search for (ripgrep syntax)."
            },
            "path": {
              "type": "string",
              "description": "File or directory to search. Defaults to the session workspace; a relative path resolves against it."
            },
            "include": {
              "type": "string",
              "description": "One glob filter for which files to search (e.g. \"*.ts\", \"*.{js,jsx}\"). Not a list; negation is not supported."
            }
          },
          "required": [
            "pattern"
          ]
        }
      },
      {
        "name": "web_search",
        "description": "Search the web for current information. Returns an optional summary answer and a list of source URLs.",
        "parameters": {
          "type": "object",
          "properties": {
            "query": {
              "type": "string",
              "description": "The search query."
            }
          },
          "required": [
            "query"
          ]
        }
      },
      {
        "name": "workflow",
        "description": "Run a JavaScript workflow script that orchestrates subagents at scale. Use this for work that fans out across many independent pieces — an audit over many files, a migration, multi-angle research, adversarial verification of findings — where you write the orchestration as a script instead of delegating turn by turn.\n\nThe workflow's identity rides the `meta` parameter as JSON: required `name` (short kebab-case) and `description` strings, optional `whenToUse` string and `phases` array (`{title, detail?, provider?, model?}`). The `script` parameter is the plain JavaScript body ONLY (NOT TypeScript, and NO `export const meta` statement — meta is a parameter, not code), running with top-level await; end with `return <value>` — the value must be JSON-serializable and is this tool's result.\n\nScript-body hooks:\n- `agent(prompt, opts?): Promise<any>` — run one subagent to completion. Without `opts.schema` it resolves to the child's final text; with `opts.schema` (an object-rooted JSON Schema using ONLY type/properties/required/additionalProperties/items/enum/const/oneOf — no pattern/format/numeric bounds) it resolves to the validated object. Resolves `null` when the child fails (filter with `.filter(Boolean)`). Other opts: `label` (display), `phase` (progress group), and independent `provider`/`model` LLM target overrides (either may be provided alone). Anything else (`effort`/`isolation`/`agentType`) is rejected loudly.\n- `pipeline(items, ...stages): Promise<any[]>` — run each item through the stages independently with NO barrier between stages (prefer this for multi-stage work). Each stage receives `(prev, item, index)`. An ordinary stage throw drops that ITEM to `null` and skips its remaining stages.\n- `parallel(thunks): Promise<any[]>` — run zero-argument functions concurrently and await ALL of them (a barrier; use only when a stage genuinely needs every prior result together). A throwing thunk resolves to `null`.\n- `phase(title)` — start a progress phase; `log(message)` — narrate progress; `args` — the tool call's `args` input, verbatim.\n\nMisused hooks (bad arguments, unknown options, unsupported schemas, tripped caps) throw errors that ALWAYS kill the script — they never dissolve into a per-item `null`.\n\nConstraints: concurrency and total-agent caps apply; no filesystem, network, timers, or Node.js APIs are provided — the agents do the work, the script only coordinates them. The run executes in the foreground: this call returns when the whole script finishes.",
        "parameters": {
          "type": "object",
          "properties": {
            "script": {
              "type": "string",
              "description": "The plain-JS workflow script body (top-level await allowed; NO `export const meta` statement; end with `return <json-value>`)."
            },
            "meta": {
              "type": "object",
              "description": "The workflow identity block (plain JSON — never code).",
              "additionalProperties": true,
              "properties": {
                "name": {
                  "type": "string",
                  "description": "Short kebab-case workflow name."
                },
                "description": {
                  "type": "string",
                  "description": "One-line description of what the workflow does."
                },
                "whenToUse": {
                  "type": "string",
                  "description": "Optional guidance on when this workflow applies."
                },
                "phases": {
                  "type": "array",
                  "description": "Optional phase declarations matched by phase() calls.",
                  "items": {
                    "type": "object",
                    "additionalProperties": true,
                    "properties": {
                      "title": {
                        "type": "string",
                        "description": "The phase title phase() calls match by exact string."
                      },
                      "detail": {
                        "type": "string",
                        "description": "Optional one-line description of the phase."
                      },
                      "provider": {
                        "type": "string",
                        "description": "Optional provider override this phase is expected to use."
                      },
                      "model": {
                        "type": "string",
                        "description": "Optional model override this phase is expected to use."
                      }
                    },
                    "required": [
                      "title"
                    ]
                  }
                }
              },
              "required": [
                "name",
                "description"
              ]
            },
            "args": {
              "type": "object",
              "description": "Optional JSON input exposed to the script as the `args` global (wrap a bare list as a field, e.g. {\"files\": [...]}).",
              "additionalProperties": true
            }
          },
          "required": [
            "script",
            "meta"
          ]
        }
      },
      {
        "name": "ralph",
        "description": "Run a foreground fresh-agent Ralph loop toward one immutable objective. Use only when the direct human explicitly asks for Ralph or fresh-agent iteration. Each round opens a new child with no parent conversation or prior child session; the shared workspace is long-term memory, and only a bounded structured report crosses rounds. The call returns when a worker reports completion or a concrete blocker, or at the round limit. Ordinary long-running same-session work belongs to goal tools.",
        "parameters": {
          "type": "object",
          "properties": {
            "objective": {
              "type": "string",
              "description": "The immutable completion objective for every fresh Ralph round."
            },
            "maxRounds": {
              "type": "number",
              "description": "Optional positive safe-integer round cap, bounded by the deployment ceiling."
            }
          },
          "required": [
            "objective"
          ]
        }
      },
      {
        "name": "read",
        "description": "Read a UTF-8 text file and return line-numbered content.",
        "parameters": {
          "type": "object",
          "properties": {
            "file_path": {
              "type": "string",
              "description": "Path to read, resolved by the filesystem backend."
            },
            "offset": {
              "type": "number",
              "description": "1-based first line to return. Defaults to 1."
            },
            "limit": {
              "type": "number",
              "description": "Maximum number of lines to return. Defaults to 2000."
            }
          },
          "required": [
            "file_path"
          ]
        }
      },
      {
        "name": "write",
        "description": "Create or fully replace a UTF-8 text file.",
        "parameters": {
          "type": "object",
          "properties": {
            "file_path": {
              "type": "string",
              "description": "Path to write, resolved by the filesystem backend."
            },
            "content": {
              "type": "string",
              "description": "Full UTF-8 text content to write."
            },
            "sandbox_permissions": {
              "type": "string",
              "description": "The wider sandbox mode this file operation needs. Only valid as a one-shot retry of an operation the sandbox just denied; requires justification and user approval.",
              "enum": [
                "workspace-write",
                "danger-full-access"
              ]
            },
            "justification": {
              "type": "string",
              "description": "Required with sandbox_permissions: one sentence for the user explaining why this exact file operation needs the wider access."
            }
          },
          "required": [
            "file_path",
            "content"
          ]
        }
      },
      {
        "name": "edit",
        "description": "Edit an existing UTF-8 text file by replacing literal text.",
        "parameters": {
          "type": "object",
          "properties": {
            "file_path": {
              "type": "string",
              "description": "Path to edit, resolved by the filesystem backend."
            },
            "old_string": {
              "type": "string",
              "description": "Literal text to replace. Must match exactly."
            },
            "new_string": {
              "type": "string",
              "description": "Literal replacement text. Use an empty string to delete the match."
            },
            "replace_all": {
              "type": "boolean",
              "description": "Replace all matches. Defaults to false; when false, old_string must appear exactly once."
            },
            "sandbox_permissions": {
              "type": "string",
              "description": "The wider sandbox mode this file operation needs. Only valid as a one-shot retry of an operation the sandbox just denied; requires justification and user approval.",
              "enum": [
                "workspace-write",
                "danger-full-access"
              ]
            },
            "justification": {
              "type": "string",
              "description": "Required with sandbox_permissions: one sentence for the user explaining why this exact file operation needs the wider access."
            }
          },
          "required": [
            "file_path",
            "old_string",
            "new_string"
          ]
        }
      },
      {
        "name": "read_image",
        "description": "Read a PNG/JPEG/WebP/GIF file and return the image itself. Requires the current model to accept image input.",
        "parameters": {
          "type": "object",
          "properties": {
            "file_path": {
              "type": "string",
              "description": "Path to the image file, resolved by the filesystem backend."
            }
          },
          "required": [
            "file_path"
          ]
        }
      }
    ]
  }
}

data.arguments:
{"plugin": {"kind": "new", "idPrefix": "grx"}, "name": "greet-tool", "purpose": "Registers a model-visible `greet` tool that returns "hello <name>".", "code": {"host": "return {
  name: 'greet-tool',
  inject: ['tools'],
  apply(ctx) {
    const tool = harness.defineTool({
      name: 'greet',
      description: 'Greets a person by name, returning "hello <name>".',
      parameters: { name: { type: 'string', required: true } },
      output: {
        schema: { type: 'string' },
        render: (_args, value) => [{ type: 'text', text: value }],
      },
      async execute(args) {
        return 'hello ' + args.name
      },
    })
    const dispose = harness.registerTool(ctx, tool)
    ctx.effect(() => dispose())
  },
}"}}

content.text:
{
  "platform": "host",
  "provider": "Tool",
  "method": "listTools",
  "data": {
    "tools": [
      {
        "name": "cordis_inspect_list",
        "description": "List every Cordis Inspect Provider currently known to the Host, including local Host Providers and the latest manifests synchronized from the Client. Each entry includes its platform, purpose, read-only methods, and input/output schemas. Call this Tool before creating or modifying a Package, then select the provider and method for cordis_inspect_query from its result. Do not guess names or treat an Inspect method as a business Service that Plugin code can call.",
        "parameters": {
          "type": "object",
          "properties": {}
        }
      },
      {
        "name": "cordis_inspect_query",
        "description": "Run a read-only query explicitly declared by an Inspect Provider. platform, provider, and method must come from cordis_inspect_list, and input must satisfy that method's schema. Use this Tool before cordis_define to read exact Service methods, Event modes, Builtin signatures, Tool schemas, theme tokens, or live Slot trees and props. Host queries run locally. A Client query waits for the first valid page response and remains pending until a page answers or the Tool is cancelled. This Tool cannot invoke business Service methods or modify the runtime. For Service.listService and Event.listEvents, query without input to navigate the compact signature directory, then query the exact service or event for its structured contract and referenced types. For Slots.listSubTree, query without root to navigate the compact tree, then query the exact root for its complete registration contract and props.",
        "parameters": {
          "type": "object",
          "properties": {
            "platform": {
              "type": "string",
              "description": "Runtime platform that owns the Provider.",
              "enum": [
                "host",
                "client"
              ]
            },
            "provider": {
              "type": "string",
              "description": "Exact Provider ID returned by cordis_inspect_list."
            },
            "method": {
              "type": "string",
              "description": "Exact method name declared by the Provider manifest."
            },
            "input": {
              "description": "Optional query input; it must satisfy the method input schema."
            }
          },
          "required": [
            "platform",
            "provider",
            "method"
          ]
        }
      },
      {
        "name": "cordis_inspect_self",
        "description": "Inspect dynamic Cordis objects owned by the current Session at increasing levels of detail. With no IDs, list only Plugin summaries. With pluginId alone, return version pointers, the latest Run, and every Package summary. Only pluginId plus packageId returns that immutable Package's Host/Client source and runtime diagnostics. packageId cannot be supplied alone. Query an exact Package before handling @pluginId, repairing an asynchronous failure, or defining an updated version. This Tool is read-only: it neither executes code nor changes version pointers.",
        "parameters": {
          "type": "object",
          "properties": {
            "pluginId": {
              "type": "string",
              "description": "Stable Plugin ID returned by cordis_define or injected by @pluginId; omit it to list every current Plugin."
            },
            "packageId": {
              "type": "string",
              "description": "Exact immutable Package ID owned by pluginId; when specified, source and diagnostics are returned."
            }
          }
        }
      },
      {
        "name": "cordis_define",
        "description": "Define an immutable Cordis Package. For a new Plugin, use kind:\"new\" and provide only a semantic prefix of 3–6 lowercase English letters; the Host returns the final pluginId and packageId. To modify an existing Plugin, use kind:\"existing\" with its exact pluginId to append a Package without overwriting older versions. Provide at least one of code.host and code.client. Each value is a plain JavaScript function body that returns a Cordis Plugin; no TypeScript, JSX, or import transformation occurs. Query Inspect before depending on a Service, Event, Builtin, Slot, or token. Define only validates parameters and syntax and records source: it does not request approval, execute apply, or change currentPackageId. On success, call cordis_run with the returned IDs.",
        "parameters": {
          "type": "object",
          "properties": {
            "plugin": {
              "oneOf": [
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "kind": {
                      "type": "string",
                      "const": "new"
                    },
                    "idPrefix": {
                      "type": "string",
                      "description": "Suggested semantic prefix of 3–6 lowercase English letters; the Host adds a unique numeric suffix."
                    }
                  },
                  "required": [
                    "kind",
                    "idPrefix"
                  ]
                },
                {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "kind": {
                      "type": "string",
                      "const": "existing"
                    },
                    "pluginId": {
                      "type": "string",
                      "description": "Exact ID of an existing Plugin; the new Package is appended to that instance."
                    }
                  },
                  "required": [
                    "kind",
                    "pluginId"
                  ]
                }
              ]
            },
            "name": {
              "type": "string",
              "description": "Short, readable Package name."
            },
            "purpose": {
              "type": "string",
              "description": "One-sentence, user-facing description of the Package purpose."
            },
            "code": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "host": {
                  "type": "string",
                  "description": "Plain JavaScript function body that returns the Host-half Cordis Plugin."
                },
                "client": {
                  "type": "string",
                  "description": "Plain JavaScript function body that returns the browser Client-half Cordis Plugin."
                }
              }
            }
          },
          "required": [
            "plugin",
            "name",
            "purpose",
            "code"
          ]
        }
      },
      {
        "name": "cordis_run",
        "description": "Activate one exact Package of a dynamic Plugin. Use mode:\"run\" for the first activation, restarting currentPackageId, or rollback. When current exists, use mode:\"update\" to switch to a different Package, even if the Plugin is currently stopped. An unauthorized Client Package creates an approval request and returns awaiting-approval; an authorized Package returns starting and continues asynchronously in the browser. Neither result waits for the final outcome inside the Tool. currentPackageId changes only after complete success; on failure, the old current and target next remain. Asynchronous success, rejection, or technical failure is reported through state and steering. After a technical failure, read diagnostics with cordis_inspect_self, correct the same Plugin, and retry autonomously. Do not request approval again after the user rejects it.",
        "parameters": {
          "type": "object",
          "properties": {
            "pluginId": {
              "type": "string",
              "description": "Stable Plugin ID returned by cordis_define."
            },
            "packageId": {
              "type": "string",
              "description": "Exact immutable Package ID to activate under that Plugin."
            },
            "mode": {
              "type": "string",
              "description": "Use run for the first activation, restarting current, or rollback; use update to switch from current to a different Package.",
              "enum": [
                "run",
                "update"
              ]
            }
          },
          "required": [
            "pluginId",
            "packageId",
            "mode"
          ]
        }
      },
      {
        "name": "cordis_stop",
        "description": "Stop the current Run of a dynamic Plugin and cancel unfinished approval or activation requests. Retain the Plugin, every immutable Package, grants, currentPackageId, and nextPackageId so it can later run or update directly. Stopping an already stopped Plugin succeeds idempotently. Use this Tool to disable effects temporarily; use cordis_undefine for permanent removal.",
        "parameters": {
          "type": "object",
          "properties": {
            "pluginId": {
              "type": "string",
              "description": "Stable dynamic Plugin ID to stop."
            }
          },
          "required": [
            "pluginId"
          ]
        }
      },
      {
        "name": "cordis_undefine",
        "description": "Permanently remove a dynamic Plugin owned by the current Session. If it is running or awaiting approval, first stop it and cancel the request, then delete every Package, grant, and version pointer. After this returns, its pluginId, packageIds, @ reference, and Package business views are invalid; historical cards retain only a \"Plugin removed\" record. Do not call this Tool when versions must remain available for restart or rollback; use cordis_stop instead.",
        "parameters": {
          "type": "object",
          "properties": {
            "pluginId": {
              "type": "string",
              "description": "Stable dynamic Plugin ID to remove permanently."
            }
          },
          "required": [
            "pluginId"
          ]
        }
      },
      {
        "name": "job_output",
        "description": "Read a background job. Stream jobs return only output since the previous read; final-output jobs return their result after settlement. Every response ends with `[status: ...]`. Reads are non-blocking unless `wait: true`, which waits up to the configured cap.",
        "parameters": {
          "type": "object",
          "properties": {
            "job_id": {
              "type": "string",
              "description": "Job id returned by the tool that started the background work."
            },
