{"plugin": {"kind": "existing", "pluginId": "grx-1"}, "name": "greet-tool-fix", "purpose": "Registers the `greet` tool with correct fiber cleanup (effect returns the disposer instead of invoking it).", "code": {"host": "return {
  name: 'greet-tool',
  inject: ['tools'],
  apply(ctx) {
    const tool = harness.defineTool({
      name: 'greet',
      description: 'Greets a person by name, returning "hello <name>".',
      parameters: { name: { type: 'string', required: true } },
      output: {
        schema: { type: 'string' },
        render: (_args, value) => [{ type: 'text', text: value }],
      },
      async execute(args) {
        return 'hello ' + args.name
      },
    })
    ctx.effect(() => harness.registerTool(ctx, tool))
  },
}"}}

